ins as (
  insert into public.works
    (title, subtitle, author, genre, year, epocas, author_death_year, external_ref, slug,
     language, is_published, is_library_work, rights_status, access_type,
     source_name, source_url, license, institution_id)
  select v.title, v.subtitle, v.author, v.genre, v.year, v.epocas, v.author_death_year, v.external_ref, v.slug,
     'es', true, true, 'public_domain', 'public_download',
     'Biblioteca Digital Hispánica — Biblioteca Nacional de España', v.visor, 'CC BY 4.0 · Biblioteca Nacional de España',
     (select id from public.institutions where slug = 'biblioteca-oficial')
  from v
  where not exists (select 1 from public.works w where w.external_ref = v.external_ref and w.deleted_at is null)
  returning id, external_ref
)
insert into public.work_files (work_id, file_type, file_url, file_name, is_public)
select ins.id, 'script', v.visor, 'Leer en la Biblioteca Nacional', true
from ins join v on v.external_ref = ins.external_ref;

